# Batch 06 — Chapter VI (Articles 51–59). Independent supervisory authorities.
def rt(u, origin, cp, rtype, obj, fn, mod, cond="", note="", deriv="direct", unres="", flag="", acc="", ext_dep="", dep=""):
    return qr(u, origin, cp, rtype, obj, fn, mod, cond=cond, deriv=deriv, type_note=note, unresolved=unres, flag=flag, acc=acc, ext=ext_dep, dep=dep)
CTRL, PROC, DS, SA, COMMN, MS = "controller", "processor", "data subject", "supervisory authority", "European Commission", "Member States"
LSA = pd("lead supervisory authority", "position_type", "A56.P1", note="Role of the supervisory authority of the main/single establishment for cross-border processing; assigned by facts, not by designation.")
SAM = pd("member(s) of a supervisory authority", "position_type", "A52.P2;A53.P1", note="Office-holders; appointed under Member State law (Arts 53–54).")
APPT = pd("appointing institution (parliament, government, head of State, or independent body under Member State law)", "position_type", "A53.P1", note="Four alternative appointing categories named; instances in Member State law (outside W).")
NATINST = pd("national parliament, government and other institutions/authorities (Member State)", "position_type", "A57.P1.ptc;A59.P0", note="Addressees of advice (Art.57(1)(c)) and annual reports (Art.59); 'other authorities as designated by Member State law'.")
COURT = pd("judicial authorities / courts (Member State)", "position_type", "A55.P3;A58.P5", note="Constituted by Member State law; referred to in Arts 55(3), 58(5) and the remedies chapter.")

# ---- Article 51
n = na("A51.P1", MS, "provide for one or more independent public authorities responsible for monitoring the application of the Regulation ('supervisory authority')", "supervisory authority", "authorization/designation (establishment obligation)", "obligation", ntype="N2 (obligation to provide for; not N1)", cp_status="none", note="The Regulation does not itself constitute any supervisory authority; each exists only through Member State law (cf. Art.54(1)(a)). 'One or more' = legal multiplicity per Member State.", flag="N2-establishment")
screen("A51.P1", "Yes", "operative-assignment; position-defining", na=[n], status="Extracted", note="N2: Member States must provide for supervisory authorities (type-level position, legal multiplicity 'one or more').")
n = na("A51.P2", SA, "contribute to the consistent application of the Regulation throughout the Union; cooperate with each other and the Commission in accordance with Chapter VII", "consistent application", "cooperation/coordination", "obligation", dep="Chapter VII", cp_status="none")
q = [rt("A51.P2", SA, "other supervisory authorities and the European Commission", "information/reporting", "cooperation in accordance with Chapter VII", "cooperation/coordination", "obligation", dep="Chapter VII", note="specific forms are in Arts 60–76")]
screen("A51.P2", "Yes", "operative-assignment; relation-bearing", na=[n], qr=q, status="Extracted", note="Cooperation duty linking supervisory authorities to each other and to the Commission; forms in Chapter VII.")
n = na("A51.P3", MS + " with more than one supervisory authority", "designate the authority that represents them in the Board and set out the mechanism ensuring compliance by the other authorities with the consistency-mechanism rules", "representation in the Board; internal compliance with Art.63", "authorization/designation", "obligation", ntype="N2-designation", dep="European Data Protection Board; consistency mechanism (Art.63)", cp_status="none")
screen("A51.P3", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A51.P4", MS, COMMN, "information/reporting", "notification of the national provisions adopted pursuant to Chapter VI by 25 May 2018, and without delay of any amendment", "information provision", "obligation", cond="by 25 May 2018; subsequent amendments without delay")]
screen("A51.P4", "Yes", "relation-bearing", qr=q, status="Extracted", note="Transposition-like notification to the Commission.")

# ---- Article 52 (independence)
n = na("A52.P1", SA, "act with complete independence in performing its tasks and exercising its powers", "independence", "implementation (condition)", "obligation", cp_status="none")
n2 = na("A52.P2", "members of each supervisory authority", "remain free from external influence and neither seek nor take instructions from anybody", "independence of members", "implementation (condition)", "obligation", cp_status="none")
n3 = na("A52.P3", "members of each supervisory authority", "refrain from any action incompatible with their duties and from any incompatible occupation during the term of office", "incompatibilities", "implementation", "obligation", cp_status="none")
screen("A52.P1", "Yes", "operative-assignment", na=[n], status="Extracted")
screen("A52.P2", "Yes", "operative-assignment", na=[n2], pos=[SAM], status="Extracted")
screen("A52.P3", "Yes", "operative-assignment", na=[n3], status="Extracted")
q = [rt("A52.P4", MS, SA, "authority/control", "provision of human, technical and financial resources, premises and infrastructure necessary for effective performance, including mutual assistance, cooperation and participation in the Board", "implementation (resourcing)", "obligation", note="resource guarantee; Member State obligor, authority beneficiary")]
screen("A52.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A52.P5", MS, SA, "authority/control", "ensure the authority chooses and has its own staff subject to the exclusive direction of its member(s)", "implementation (independence)", "obligation")]
screen("A52.P5", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A52.P6", MS, SA, "oversight/supervision", "financial control which does not affect independence; separate, public annual budgets (possibly part of the national budget)", "monitoring (financial control, limited)", "obligation", note="gov-direction: Member State financial control over SA, limited by independence")]
screen("A52.P6", "Yes", "relation-bearing", qr=q, status="Extracted")

# ---- Article 53, 54
q = [rt("A53.P1", APPT, SAM, "delegation/authorization", "appointment of each member by a transparent procedure by the parliament, the government, the head of State or an independent body entrusted under Member State law", "authorization/designation (appointment)", "obligation", cond="Member States shall provide for the appointment procedure; appointment by one of four alternatives", note="obligation on Member States (N2-type) to provide for appointment; appointing institution named by category only; gov-direction: appointing institution appoints member", ext_dep="Member State law")]
screen("A53.P1", "Yes", "relation-bearing", qr=q, pos=[APPT], status="Extracted", note="Four alternative appointers (parliament, government, head of State, independent body).")
n = na("A53.P2", SAM, "have the qualifications, experience and skills, in particular in data protection, required to perform duties and exercise powers", "member qualifications", "implementation (condition)", "obligation", cp_status="none")
screen("A53.P2", "Yes", "operative-assignment", na=[n], status="Extracted")
screen("A53.P3", "No", "substantive-conduct-rule", status="Not applicable", note="End of member's duties (expiry, resignation, retirement) per Member State law.")
n = na("A53.P4", "(dismissing authority — not stated)", "dismiss a member only in cases of serious misconduct or if conditions for performing duties are no longer fulfilled", "dismissal of members", "authorization/designation (limit on removal)", "prohibition (except)", cp_status="none", counterpart=SAM, flag="subject-unstated")
screen("A53.P4", "Uncertain", "norm-without-named-subject", na=[n], status="Extracted", note="Protection against dismissal; authority competent to dismiss not named.")
n = na("A54.P1", MS, "provide by law for: (a) the establishment of each supervisory authority; (b)-(f) qualifications, appointment rules and procedures, term of office (no less than four years), reappointment, obligations and incompatibilities of members and staff", "establishment and organisation of supervisory authorities", "authorization/designation (establishment by national law)", "obligation", ntype="N2 (obligation to provide by law for establishment)", cp_status="none", note="Confirms that the supervisory authorities are constituted by Member State law (outside W); the GDPR obliges Member States to do so.", flag="N2-establishment", dep="Member State law")
screen("A54.P1", "Yes", "operative-assignment; position-defining", na=[n], status="Extracted", note="N2 (a): 'provide by law for the establishment of each supervisory authority'.")
n = na("A54.P2", "members and staff of each supervisory authority", "be subject to a duty of professional secrecy during and after the term of office, including regarding reporting by natural persons of infringements", "professional secrecy", "implementation", "obligation", cond="in accordance with Union or Member State law", cp_status="none")
screen("A54.P2", "Yes", "operative-assignment", na=[n], status="Extracted")
ext("A53.P1;A54.P1", "Member State law establishing and organising each supervisory authority", "other_normative", "constitutes_position (supervisory authority instances, their members, appointment rules)", "constitutes", "All instances of the supervisory authority, their legal form, multiplicity and appointment depend on national law outside W; the GDPR specifies only tasks, powers, competence and independence requirements at type level.")

# ---- Article 55, 56 (competence)
n = na("A55.P1", SA, "be competent for the tasks assigned and powers conferred by the Regulation on the territory of its own Member State", "territorial competence", "competence allocation", "competence", cp_status="none")
screen("A55.P1", "Yes", "operative-assignment (competence allocation)", na=[n], status="Extracted")
n = na("A55.P2", SA + " of the Member State concerned", "be competent where processing is carried out by public authorities or private bodies acting on the basis of Art.6(1)(c) or (e); Art.56 does not apply", "competence for public-interest processing", "competence allocation", "competence", cond="processing by public authorities or private bodies acting under Art.6(1)(c),(e)", cp_status="none", note="Excludes the lead-authority mechanism.")
screen("A55.P2", "Yes", "operative-assignment (competence allocation)", na=[n], status="Extracted")
n = na("A55.P3", SA, "not be competent to supervise processing operations of courts acting in their judicial capacity", "exclusion of courts' judicial processing", "competence allocation (exclusion)", "prohibition (competence limit)", cp_status="none", counterpart=COURT)
screen("A55.P3", "Yes", "operative-assignment (competence limit)", na=[n], pos=[COURT], status="Extracted", note="Boundary between SA competence and courts.")
q = [rt("A56.P1", LSA, CTRL + " / " + PROC + " (cross-border processing)", "authority/control", "competence to act as lead supervisory authority for cross-border processing in accordance with the procedure of Art.60", "competence allocation (lead authority)", "competence", cond="authority of the main establishment or single establishment; without prejudice to Art.55", dep="Art.60 procedure", note="gov-direction: LSA supervises controller/processor for cross-border processing")]
screen("A56.P1", "Yes", "relation-bearing; competence allocation", qr=q, pos=[LSA], status="Extracted", note="One-stop-shop competence; procedure in Art.60.")
n = na("A56.P2", SA, "be competent to handle a complaint or possible infringement if the subject matter relates only to an establishment in its Member State or substantially affects data subjects only there", "local competence derogation", "competence allocation", "competence", cond="subject matter relates only to an establishment in its Member State or substantially affects data subjects only in it", cp_status="none")
screen("A56.P2", "Yes", "operative-assignment (competence allocation)", na=[n], status="Extracted")
q = [rt("A56.P3", SA + " (local)", LSA, "information/reporting", "information to the lead supervisory authority without delay about local-case matters", "information provision", "obligation", cond="cases under 56(2)"),
     rt("A56.P3", LSA, SA + " (local)", "authority/control", "decision within three weeks whether it will handle the case under Art.60", "competence allocation (decision)", "obligation", cond="after being informed; taking into account the existence of an establishment in the informing authority's Member State", note="gov-direction: LSA decides which authority handles the case")]
screen("A56.P3", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A56.P4", SA + " (informing)", LSA, "representation/participation", "submission of a draft decision; the lead authority takes utmost account when preparing the Art.60(3) draft", "participation", "permission", cond="lead authority decides to handle the case", dep="Art.60(3)", note="duty of the lead authority to take utmost account of the draft")]
screen("A56.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A56.P5", SA + " (informing)", "(handling under Arts 61–62)", "authority/control", "handling of the case under Articles 61 and 62 if the lead authority decides not to handle it", "competence allocation", "obligation", cond="lead authority decides not to handle the case", dep="Arts 61–62", cp=None) if False else rt("A56.P5", SA + " (informing)", SA + " (other, via Arts 61–62)", "information/reporting", "handling of the case according to Arts 61 and 62 (mutual assistance, joint operations)", "competence allocation", "obligation", cond="lead authority decides not to handle the case", dep="Arts 61–62")]
screen("A56.P5", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted")
q = [rt("A56.P6", LSA, CTRL + " / " + PROC, "authority/control", "sole interlocutor of the controller or processor for cross-border processing", "interface (exclusive channel)", "declaratory", cond="cross-border processing carried out by that controller or processor", note="a legally constituted interface (exclusive channel) without a separate device")]
screen("A56.P6", "Yes", "relation-bearing", qr=q, status="Extracted", note="Interface-type relation: the lead authority is the single interlocutor.")

# ---- Article 57 (tasks) — points inventoried; new relations extracted; duplicates linked
n = na("A57.P1", SA, "on its territory perform the tasks (a)-(v), without prejudice to other tasks under the Regulation", "tasks of the supervisory authority", "monitoring; enforcement; information provision; rule-making; advice; cooperation", "obligation", cond="on its territory", cp_status="none", note="22 points inventoried; relation-bearing points are extracted separately below; points whose relations were already extracted are linked (many-to-many provenance).")
q1 = rt("A57.P1.pta", SA, CTRL + " and " + PROC, "oversight/supervision", "monitoring and enforcement of the application of the Regulation", "monitoring; enforcement", "obligation", cond="on its territory", note="gov-direction: SA supervises controllers and processors (general supervisory relation)")
q2 = rt("A57.P1.ptc", SA, NATINST, "information/reporting", "advice, in accordance with Member State law, on legislative and administrative measures relating to the protection of natural persons' rights and freedoms with regard to processing", "interpretation/advice", "obligation", note="gov-direction: SA advises national institutions; also 58(3)(b)", ext_dep="Member State law")
q3 = rt("A57.P1.pte", SA, DS, "information/reporting", "upon request, information on the exercise of rights; cooperation with other SAs to that end", "information provision", "obligation", cond="upon request")
q4 = rt("A57.P1.ptf", SA, DS + " (or body, organisation or association under Art.80)", "review/adjudication", "handling complaints, investigating the subject matter to the extent appropriate, informing the complainant of the progress and the outcome of the investigation within a reasonable period", "adjudication/dispute resolution (administrative)", "obligation", cond="complaint lodged by a data subject or by a body, organisation or association under Art.80", note="complaint-handling relation; the corresponding right to lodge a complaint is in Art.77; judicial remedy against the SA in Art.78", dep="Art.77, Art.78, Art.80", acc="INFO/ANSWERABILITY candidate (duty to inform complainant of progress and outcome; reasons not required here) — see Art.78")
q5 = rt("A57.P1.ptg", SA, "other supervisory authorities", "information/reporting", "cooperation, including sharing information and mutual assistance, to ensure consistency of application and enforcement", "cooperation/coordination", "obligation", note="peer cooperation among SAs; forms in Arts 60–62")
q6 = rt("A57.P1.pth", SA, CTRL + " / " + PROC + " (and other public authorities as information sources)", "oversight/supervision", "investigations on the application of the Regulation, including on the basis of information received from another SA or other public authority", "monitoring (investigation)", "obligation")
q7 = rt("A57.P1.ptt", SA, BOARD, "representation/participation", "contribution to the activities of the Board", "participation", "obligation")
screen("A57.P1", "Yes", "operative-assignment; relation-bearing; many-to-many provenance", na=[n], qr=[q1, q2, q3, q4, q5, q6, q7], status="Extracted", note="Points (a),(c),(e),(f),(g),(h),(t) extracted as QR; (j),(k),(l),(m),(n),(o),(p),(q),(r),(s) linked to relations extracted at Arts 28(8), 35(4), 36(2), 40(5), 42, 43, 41, 46(3), 47; (b),(d),(i),(u),(v) are awareness, monitoring-of-developments, internal records and residual tasks (NA only: awareness and monitoring of developments are information/monitoring tasks without a counterpart).")
n_aw = na("A57.P1.ptb;A57.P1.ptd;A57.P1.pti;A57.P1.ptu;A57.P1.ptv", SA, "(b) promote public awareness; (d) promote controllers'/processors' awareness; (i) monitor relevant developments; (u) keep internal records of infringements and measures under Art.58(2); (v) fulfil any other tasks", "awareness, monitoring of developments, internal records, residual tasks", "information provision; monitoring", "obligation", cp_status="none")
link("na", "object", "standard contractual clauses", "A57.P1.ptj", origin_sub="supervisory authority")
link("na", "object", "list of operations requiring DPIA", "A57.P1.ptk")
link("qr", "object", "written advice within up to eight weeks", "A57.P1.ptl;A58.P3.pta")
link("qr", "object", "approval of the draft code", "A57.P1.ptm;A58.P3.ptd")
link("na", "object", "codes of conduct", "A57.P1.ptm", origin_sub="Member States, supervisory authorities")
link("na", "object", "certification mechanisms", "A57.P1.ptn", origin_sub="Member States, supervisory authorities")
link("qr", "object", "issue of certification on the basis of criteria", "A57.P1.ptn;A58.P3.ptf")
link("qr", "object", "issue (max. three years), renewal and withdrawal", "A57.P1.pto")
link("na", "object", "publication of accreditation requirements and certification criteria", "A57.P1.ptp")
link("qr", "object", "submission of draft requirements for accreditation", "A57.P1.ptp")
link("qr", "object", "accreditation of a body with appropriate expertise", "A57.P1.ptq;A58.P3.pte;A58.P3.ptd") if False else None
link("qr", "object", "accreditation of a body with appropriate expertise", "A57.P1.ptq")
link("qr", "object", "accreditation of certification bodies (alternative (a))", "A57.P1.ptq;A58.P3.pte")
link("qr", "object", "authorisation of safeguards by (a) contractual clauses", "A57.P1.ptr;A58.P3.pth;A58.P3.pti")
link("qr", "object", "approval of binding corporate rules", "A57.P1.pts;A58.P3.ptj")
q = [rt("A57.P2", SA, DS, "beneficiary/protective", "facilitation of the submission of complaints (e.g. an electronically completable form)", "implementation (facilitation)", "obligation")]
screen("A57.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A57.P3", SA, "perform tasks free of charge for the data subject and, where applicable, the DPO", "fees", "implementation", "obligation", cp_status="none")
screen("A57.P3", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A57.P4", SA, DS, "authority/control", "reasonable fee or refusal to act on manifestly unfounded or excessive requests; the SA bears the burden of demonstration", "implementation (competence)", "permission", cond="manifestly unfounded or excessive requests", note="mirrors Art.12(5)", flag="type-uncertain")]
screen("A57.P4", "Yes", "relation-bearing", qr=q, status="Extracted")

# ---- Article 58 (powers)
q = [rt("A58.P1", SA, CTRL + " / " + PROC + " (and their representatives)", "oversight/supervision", "investigative powers: (a) order to provide information; (b) data protection audits; (c) review of certifications issued under Art.42(7); (d) notification of an alleged infringement; (e) access to all personal data and information; (f) access to premises and equipment in accordance with Union or Member State procedural law", "monitoring (investigation)", "competence", cond="(f) in accordance with Union or Member State procedural law", note="gov-direction: SA investigates controllers/processors; (c) concerns certifications (relation to certification bodies as well)")]
screen("A58.P1", "Yes", "relation-bearing", qr=q, status="Extracted", note="Six investigative powers (a)-(f).")
q = [rt("A58.P2", SA, CTRL + " / " + PROC, "authority/control", "corrective powers: (a) warnings; (b) reprimands; (c) order to comply with data subject requests; (d) order to bring processing into compliance; (e) order to communicate a breach to the data subject; (f) temporary or definitive limitation including a ban; (g) order rectification/erasure/restriction and notifications; (i) administrative fine (Art.83); (j) suspension of data flows to a third-country recipient or international organisation", "enforcement", "competence", cond="depending on the circumstances of each case; fines in addition to or instead of other measures", note="gov-direction: SA sanctions controllers/processors; (i) links to Art.83", dep="Art.83"),
     rt("A58.P2", SA, CB + " (and controller/processor)" if False else "certification body (Art.43)", "authority/control", "(h) withdrawal of a certification or order to the certification body to withdraw a certification, or not to issue one, if the requirements for the certification are not or are no longer met", "enforcement (over certification)", "competence", cond="requirements for the certification not or no longer met", note="direct power over the certification body and, through certification, over the certified controller/processor; links Art.43(1) (information before issuing) and 42(7)", dep="Arts 42, 43")]
screen("A58.P2", "Yes", "relation-bearing", qr=q, status="Extracted", note="Ten corrective powers (a)-(j); (h) is the SA's power over certification and certification bodies.")
q = [rt("A58.P3", SA, NATINST + " and the public", "information/reporting", "opinions on any issue related to the protection of personal data, on its own initiative or on request, to the national parliament, the government, other institutions and bodies, and the public", "interpretation/advice", "competence", cond="to other institutions in accordance with Member State law", ext_dep="Member State law")]
n = na("A58.P3.ptc", SA, "authorise processing referred to in Art.36(5) if the law of the Member State requires prior authorisation", "prior authorisation of processing", "authorization", "competence", cond="Member State law requires prior authorisation", dep="Member State law (Art.36(5))", cp_status="none", note="Authorization power exists only if national law requires it; relation to controllers arises under that law.")
screen("A58.P3", "Yes", "relation-bearing; many-to-many provenance", na=[n], qr=q, status="Extracted", note="Authorisation and advisory powers (a)-(j): (a),(d),(e),(f),(g),(h),(i),(j) linked to relations extracted at Arts 36, 40, 43, 42, 28/46, 46(3), 47; (b) and (c) extracted here.")
link("na", "object", "standard contractual clauses", "A58.P3.ptg", origin_sub="supervisory authority")
n = na("A58.P4", "(Union and Member State law)", "subject the exercise of the SA's powers to appropriate safeguards, including effective judicial remedy and due process, in accordance with the Charter", "safeguards on SA powers", "review/adjudication (constraint)", "obligation", counterpart=SA, cp_status="none", flag="subject-unstated", note="Links SA powers to judicial review (Art.78).", dep="Art.78")
screen("A58.P4", "Yes", "operative-assignment (constraint)", na=[n], status="Extracted", note="Constraint on SA powers; the review relation is in Arts 78–79.")
n = na("A58.P5", MS, "provide by law that the supervisory authority has the power to bring infringements to the attention of judicial authorities and, where appropriate, to commence or engage in legal proceedings to enforce the Regulation", "SA power to litigate/refer", "enforcement (recourse to courts)", "obligation", ntype="N2-like (obligation to confer a power by national law)", cp_status="none", dep="Member State law", counterpart=COURT)
q = [rt("A58.P5", SA, COURT, "information/reporting", "power to bring infringements to the attention of judicial authorities and to commence or engage in legal proceedings", "enforcement (referral/litigation)", "competence", cond="as provided by Member State law", note="competence exists only as conferred by Member State law (N2-like)", ext_dep="Member State law", deriv="derived", unres="power depends on national implementing law")]
screen("A58.P5", "Yes", "operative-assignment; relation-bearing (derived)", na=[n], qr=q, status="Extracted", note="Competence conferred through Member State law (external dependency).")
n = na("A58.P6", MS, "may provide by law that the SA has additional powers; their exercise shall not impair the effective operation of Chapter VII", "additional powers", "rule-making (extension)", "permission (competence)", cp_status="none", dep="Chapter VII", counterpart=SA)
screen("A58.P6", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")

# ---- Article 59
q = [rt("A59.P0", SA, NATINST, "information/reporting", "transmission of the annual report on its activities to the national parliament, the government and other authorities designated by Member State law", "information provision (reporting)", "obligation", cond="report may include a list of types of infringement notified and measures taken under Art.58(2)", acc="INFO (forum identified by category/Member State law; duty to explain/justify and questioning capacity not stated in the GDPR; any accountability arrangement would be constituted by Member State law)", note="reporting line; accountability, if any, lies outside W", ext_dep="Member State law"),
     rt("A59.P0", SA, "the public, the European Commission and the Board", "information/reporting", "availability of the annual reports to the public, the Commission and the Board", "information provision (publication)", "obligation")]
screen("A59.P0", "Yes", "relation-bearing", qr=q, status="Extracted", note="Annual report: reporting to national institutions and publication to the Commission and the Board (INFO).")
